def solve_equation():
    solutions = []
    limit = 10

    print("Searching for positive integer solutions (a, b, c) to 2^a + 3^b + 1 = 6^c for a, b, c <= 10.")

    for a in range(1, limit + 1):
        for b in range(1, limit + 1):
            lhs = (2**a) + (3**b) + 1

            for c in range(1, limit + 1):
                rhs = 6**c

                if lhs == rhs:
                    solutions.append((a, b, c))

    return solutions

solutions = solve_equation()
print("Found solutions (a, b, c):", solutions)

